/**
 * Check for failed files before routing to target system.
 *
 * Reads entry.failed_files accumulated by Classify attachments and Fetch files.
 * Patches entry.text with a notice for the receiving system.
 * Emits a notification payload on output 2 back to the original sender.
 *
 * Runs BEFORE Bridge entry to client so the text patch is written
 * into the correct field by each adapter (text for Rayvn, content for WaSOS).
 *
 * Output 1: msg continues (always)
 * Output 2: notification payload (only when failed_files is non-empty)
 */
const entry       = msg.entry;
const failed      = (entry && entry.failed_files) || [];

if (failed.length === 0) return [msg, null];

const total   = ((entry.files || []).length) + failed.length;
const notice  = " [" + failed.length + "/" + total
              + " vedlegg ikke overført. Avsender mottar instruks om alternativ håndtering]";

entry.text = (entry.text || "") + notice;

const notification = {
    payload: {
        entry_id:     entry.id,
        failed_files: failed,
        total_files:  total,
        succeeded:    (entry.files || []).length,
        entry_author: entry.author,
        metadata:     entry.metadata
    }
};

return [msg, notification];
